create extension if not exists pgcrypto;

create table if not exists public.people (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  name text not null,
  role text default '',
  cluster text default '',
  portfolios text default '',
  first_one_on_one date,
  sommos text default '',
  performance int default 3 check (performance between 1 and 5),
  potential int default 3 check (potential between 1 and 5),
  succession text default '',
  development text default '',
  notes text default '',
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

create table if not exists public.stakeholders (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  name text not null,
  area text default '',
  role text default '',
  influence text default 'Media',
  relationship text default 'Media',
  expectations text default '',
  learnings text default '',
  next_action text default '',
  next_meeting date,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

create table if not exists public.suppliers (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  name text not null,
  category text default '',
  spend numeric(16,2) default 0,
  criticality text default 'Media',
  contact text default '',
  meetings int default 0,
  opportunities text default '',
  risks text default '',
  action_plan text default '',
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

create table if not exists public.categories (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  name text not null,
  strategy text default '',
  owner text default '',
  opportunities text default '',
  risks text default '',
  savings numeric(16,2) default 0,
  status text default 'Mapear',
  spend numeric(16,2) default 0,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

create table if not exists public.diagnosis (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade unique,
  situation text default 'Turnaround leve / Realignment',
  challenges text default '',
  hypotheses text default '',
  risks text default '',
  opportunities text default '',
  learnings text default '',
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

alter table public.people enable row level security;
alter table public.stakeholders enable row level security;
alter table public.suppliers enable row level security;
alter table public.categories enable row level security;
alter table public.diagnosis enable row level security;

grant select, insert, update, delete on public.people to authenticated;
grant select, insert, update, delete on public.stakeholders to authenticated;
grant select, insert, update, delete on public.suppliers to authenticated;
grant select, insert, update, delete on public.categories to authenticated;
grant select, insert, update, delete on public.diagnosis to authenticated;

do $$ begin
  create policy people_owner_all on public.people for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
exception when duplicate_object then null; end $$;
do $$ begin
  create policy stakeholders_owner_all on public.stakeholders for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
exception when duplicate_object then null; end $$;
do $$ begin
  create policy suppliers_owner_all on public.suppliers for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
exception when duplicate_object then null; end $$;
do $$ begin
  create policy categories_owner_all on public.categories for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
exception when duplicate_object then null; end $$;
do $$ begin
  create policy diagnosis_owner_all on public.diagnosis for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
exception when duplicate_object then null; end $$;

create or replace function public.touch_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists touch_people_updated_at on public.people;
create trigger touch_people_updated_at before update on public.people for each row execute function public.touch_updated_at();
drop trigger if exists touch_stakeholders_updated_at on public.stakeholders;
create trigger touch_stakeholders_updated_at before update on public.stakeholders for each row execute function public.touch_updated_at();
drop trigger if exists touch_suppliers_updated_at on public.suppliers;
create trigger touch_suppliers_updated_at before update on public.suppliers for each row execute function public.touch_updated_at();
drop trigger if exists touch_categories_updated_at on public.categories;
create trigger touch_categories_updated_at before update on public.categories for each row execute function public.touch_updated_at();
drop trigger if exists touch_diagnosis_updated_at on public.diagnosis;
create trigger touch_diagnosis_updated_at before update on public.diagnosis for each row execute function public.touch_updated_at();

create or replace function public.seed_first100days_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.diagnosis (user_id, situation, challenges, hypotheses, risks, opportunities)
  values (new.id, 'Turnaround leve / Realignment', 'Pessoas e performance; org design; stakeholders criticos; fornecedores estrategicos; captura de valor; SAP S/4HANA; comunicacao e governanca.', 'Existe valor capturavel com foco nas maiores categorias, maior cadencia de governanca e redefinicao clara das carteiras.', 'Perda de foco nos primeiros 30 dias, ruido com stakeholders, baixa clareza de papeis e dependencia de dados dispersos.', 'Priorizacao por spend, early wins em contratos de alto impacto, melhoria da rotina financeira e fortalecimento do time.')
  on conflict (user_id) do nothing;

  insert into public.people (user_id, name, role, cluster, performance, potential)
  select new.id, p.name, p.role, case when p.name = 'Juliana Cardoso Gomes' then 'Lideranca' else 'A definir' end, 3, 3
  from jsonb_to_recordset($people$[{"name": "Juliana Cardoso Gomes", "role": "Coordenadora"}, {"name": "Joao Victor", "role": "Analista Sr"}, {"name": "Thais Gois", "role": "Consultora"}, {"name": "Pedro Escobar", "role": "Analista Sr"}, {"name": "Bruna Ferreira", "role": "Analista Pl"}, {"name": "Gabriel Menezes", "role": "Consultor"}, {"name": "Keyze", "role": "Consultora Sr"}, {"name": "Denis", "role": "Analista Sr"}, {"name": "Rhenan Caetano", "role": "Analista Sr"}, {"name": "Rafael Iury", "role": "Analista Pl"}, {"name": "Isabella da Silva", "role": "Estagiaria"}]$people$::jsonb) as p(name text, role text);

  insert into public.stakeholders (user_id, name, area, role, influence, relationship, next_action)
  select new.id, s.name, s.area, s.role, case when s.name = 'Diretoria de Suprimentos' then 'Alta' else 'Media' end, 'Media', 'Agendar conversa inicial'
  from jsonb_to_recordset($stakeholders$[{"name": "Diretoria de Suprimentos", "area": "Lideranca", "role": "Sponsor"}, {"name": "RH", "area": "Pessoas", "role": "Parceiro"}, {"name": "TI", "area": "Tecnologia", "role": "Parceiro"}, {"name": "Facilities", "area": "Cliente interno", "role": "Stakeholder"}, {"name": "Marketing", "area": "Cliente interno", "role": "Stakeholder"}, {"name": "Juridico", "area": "Governanca", "role": "Parceiro"}, {"name": "Financas", "area": "Financeiro", "role": "Parceiro"}]$stakeholders$::jsonb) as s(name text, area text, role text);

